int cmpTang(const void *a, const void *b){
    int x = *(const int *)a;
    int y = *(const int *)b;
    if(x < y) return -1;
    if(x > y) return 1;
    return 0;
}
// Giam dan: doi cho tham so
int cmpGiam(const void *a, const void *b){ return cmpTang(b, a); }

int a[] = {3, 1, 2, 5, 6, 4, 8, 9, 10, 7};
int n = 10;
qsort(a, n, sizeof(a[0]), cmpTang);  // 1 2 3 ... 10
qsort(a, n, sizeof(a[0]), cmpGiam);  // 10 9 8 ... 1
